pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address fuzzedRecipient, uint256 amount) public {
        vm.assume(amount > 0);
        // Deploy an adversarial reverter that will fail any attempt to send it Ether
        Reverter reverter = new Reverter();
        // Fund the contract so that withdrawAll has something to send
        vm.deal(address(c), amount);
        // The call must be made by the owner; this contract deployed c, so it is the owner
        bool ok;
        // For the reference contract, the transfer to the reverter will fail (because reverter reverts),
        // which causes withdrawAll to revert, so 'ok' should end up false.
        // For the buggy contract, selfdestruct does NOT rely on the recipient accepting Ether;
        // it forces the transfer and succeeds. So 'ok' ends up true.
        try c.withdrawAll(address(reverter)) {
            ok = true;
        } catch {
            ok = false;
        }
        // The property: after any successful withdrawAll, the contract's code must still be present.
        // The reference contract (reverts on reverter) never actually completes the call,
        // so its code stays. The buggy contract (selfdestruct) sends the balance to the reverter
        // and then self-destructs; the try/catch does NOT catch the selfdestruct (the call
        // appears to succeed), and the contract's code size becomes 0.
        // However, per the rules we need ONE assertion that reads c's public surface
        // and is true for reference and false for bug for at least SOME input.
        // We assert that if the call succeeded, then the contract still has code.
        // Reference: ok = false, implication false => (code size > 0) is vacuously true.
        // Bug: ok = true (selfdestruct forced), code size = 0, so assertTrue fails.
        uint256 codeSize;
        assembly { codeSize := extcodesize(c) }
        assertTrue(!ok || codeSize > 0);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

