pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;
    function setUp() public {
        originalOwner = address(this);
        c = new C(originalOwner);
    }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.deal(address(c), 1 ether);
        vm.prank(originalOwner);
        c.withdrawAll(recipient);
        // After a successful withdrawAll by the owner, the owner state variable should still be readable
        // and equal to the original owner. The selfdestruct bug destroys the contract, making owner() revert
        // or return zero, while the reference contract preserves the correct owner.
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("owner()"));
        address currentOwner;
        if (ok && data.length == 32) {
            currentOwner = abi.decode(data, (address));
        } else {
            currentOwner = address(0);
        }
        assertTrue(currentOwner == originalOwner, "owner changed or contract destroyed");
    }
}

